#include "../../04-图论/支配树.cpp"
vector<int> dominator_tree(const vector<vector<int>> &arg_g,int root){g=arg_g;return dominator_tree(root);}
int main(){mt19937 r(109);for(int t=0;t<500;t++){int n=1+r()%15,s=r()%n;vector<vector<int>>g(n);for(int u=0;u<n;u++)for(int v=0;v<n;v++)if(r()%6==0)g[u].push_back(v);auto reach=[&](int ban){vector<bool> vis(n);if(s==ban)return vis;queue<int>q;q.push(s);vis[s]=1;while(!q.empty()){int u=q.front();q.pop();for(int v:g[u])if(v!=ban&&!vis[v])vis[v]=1,q.push(v);}return vis;};auto all=reach(-1);auto ans=dominator_tree(g,s);vector<vector<bool>> d(n,vector<bool>(n));for(int ban=0;ban<n;ban++){auto vis=reach(ban);for(int v=0;v<n;v++)d[v][ban]=all[v]&&!vis[v];}for(int v=0;v<n;v++)if(v==s||!all[v])assert(ans[v]==-1);else{int want=-1;for(int u=0;u<n;u++)if(u!=v&&d[v][u]){bool closest=true;for(int w=0;w<n;w++)if(w!=u&&w!=v&&d[v][w]&&!d[u][w])closest=false;if(closest)want=u;}assert(ans[v]==want);}}vector<vector<int>> chain(100000);for(int i=1;i<100000;i++)chain[i-1].push_back(i);auto a=dominator_tree(chain,0);assert(a.back()==99998);}
